{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect Meeting Requirements",
        "actor": "Meeting Organizer",
        "system": "Unspecified (form, calendar, or manual collection)",
        "inputs": ["Meeting date", "Meeting time", "Participant count"],
        "outputs": ["Meeting requirements record"]
      },
      {
        "id": "A2",
        "name": "Check Room Availability",
        "actor": "Meeting Organizer",
        "system": "Room reservation system; Calendar system",
        "inputs": ["Meeting requirements record"],
        "outputs": ["Room availability status", "List of available rooms"]
      },
      {
        "id": "A3",
        "name": "Select Suitable Room",
        "actor": "Meeting Organizer",
        "system": "Room reservation system",
        "inputs": ["List of available rooms", "Meeting requirements record"],
        "outputs": ["Selected room"]
      },
      {
        "id": "A4",
        "name": "Reserve Selected Room",
        "actor": "Meeting Organizer",
        "system": "Room reservation system",
        "inputs": ["Selected room", "Meeting date", "Meeting time"],
        "outputs": ["Confirmed room reservation"]
      },
      {
        "id": "A5",
        "name": "Create or Update Calendar Invitation",
        "actor": "Meeting Organizer",
        "system": "Calendar system",
        "inputs": ["Confirmed room reservation", "Participant list"],
        "outputs": ["Updated calendar invitation with room details"]
      },
      {
        "id": "A6",
        "name": "Notify Participants of Room Information",
        "actor": "Meeting Organizer",
        "system": "Email system or collaboration/messaging tool",
        "inputs": ["Updated calendar invitation with room details", "Participant list"],
        "outputs": ["Participant notification sent"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is a suitable room available for the requested date, time, and participant count?",
        "branches": [
          {
            "outcome": "Available",
            "next": "A3"
          },
          {
            "outcome": "Not Available",
            "next": "EXCEPTION_E1"
          }
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
