    },
    {
      "id": "G3",
      "area": "Reservation Cancellation and Modification Process",
      "description": "There is no defined process for cancelling or modifying a confirmed reservation. Responsible parties, initiation steps, and participant notification procedures in such cases are unknown."
    },
    {
      "id": "G4",
      "area": "Reservation Conflict Resolution",
      "description": "How a reservation conflict discovered after confirmation is detected, escalated, and resolved is not described. It is unclear whether the system detects conflicts automatically or if manual reporting is required."
    },
    {
      "id": "G5",
      "area": "Participant Count Change Handling",
      "description": "If the participant count changes after reservation, the process for reassessing room suitability and potentially rebooking is not specified."
    },
    {
      "id": "G6",
      "area": "Room Selection Criteria",
      "description": "The criteria used to select among available rooms (e.g., proximity, equipment, capacity buffer) are not defined, limiting the ability to automate or standardize room selection."
    },
    {
      "id": "G7",
      "area": "Notification Channel Determination",
      "description": "Whether participants are notified via email, a collaboration/messaging tool, or both — and how the channel is chosen — is not specified."
    }
  ]
